#include <iostream> #include <stdexcept> // std::out_of_range, std::invalid_argument 예외 클래스 제공 class MyArray { private: static const int MAX_SIZE = 100; // 정적 배열의 최대 크기 (상수 정의) int _size; // 사용자가 지정한 실제 배열 크기 int _array[MAX_SIZE]; // 스택에 고정 할당된 정적 배열 public: // 생성자 // 1. create(size): 최대 크기 이내로 배열 크기를 지정하여 생성 및 초기화 MyArray(int size) : _size(size) { if (size <= 0 || size > MAX_SIZE) { throw std::invalid_argument("배열 크기는 1 이상, 최대 크기(100) 미만이어야 합니다."); } // 배열 요소 전체 0으로 초기화 for (int i = 0; i < MAX_SIZE; ++i) { _array[i] = 0; } } // 소멸자: 정적 배열은 스택에 자동 생성되므로 별도의 메모리 해제(delete)가 필요 없음 // 컴파일러가 만들어주는 기본 소멸자(Default Destructor)를 명시적으로 생성하도록 지시하는 C++11 이후의 문법 ~MyArray() = default; // 2. get(index): 지정한 index의 값 반환 // const는 "이 멤버 함수는 객체의 내부 상태를 변경하지 않는 읽기 전용(Constant) 함수임을 // 컴파일러와 사용자에게 보장한다"는 의미 int get(int index) const { if (index < 0 || index >= _size) { throw std::out_of_range("Index Out of Bound)"); } return _array[index]; } // 3. set(index, value): 지정한 index에 값 저장 void set(int index, int value) { if (index < 0 || index >= _size) { throw std::out_of_range("Index Out of Bound)"); } _array[index] = value; } // 4. size(): 현재 설정된 배열의 크기 반환 int size() const { return _size; } // 5. find(value): 값의 위치(index) 탐색 int find(int value) const { for (int i = 0; i < _size; ++i) { if (_array[i] == value) { return i; } } return -1; } // 6. display(): 배열 데이터 출력 void display() const { std::cout << "Array(size=" << _size << "): ["; for (int i = 0; i < _size; ++i) { std::cout << _array[i]; if (i < _size - 1) { std::cout << ", "; } } std::cout << "]
"; } }; // === 실제 사용 예시 === int main() { try { MyArray arr(5); std::cout << "정적 배열 생성 완료! 현재 크기: " << arr.size() << "
"; arr.set(0, 10); arr.set(1, 20); arr.set(2, 30); arr.set(3, 40); arr.set(4, 50); arr.display(); std::cout << "2번 인덱스의 값: " << arr.get(2) << "
"; int idx = arr.find(30); std::cout << "'30'의 위치(index): " << idx << "
"; } catch (const std::exception& e) { std::cerr << "에러: " << e.what() << "
"; } return 0; }

#include <iostream> #include <stdexcept> class MyArray2D { private: int _rows; int _cols; int* _matrix; // 원시 포인터를 이용한 동적 배열 관리 public: // 1. 생성자: rows x cols 크기의 메모리를 동적 할당하고 0으로 초기화 MyArray2D(int rows, int cols) : _rows(rows), _cols(cols) { if (rows <= 0 || cols <= 0) { throw std::invalid_argument("행과 열의 크기는 1 이상이어야 합니다."); } // 1차원 연속 메모리로 할당 후 0으로 초기화 _matrix = new int[rows * cols](); } // 소멸자: 동적 할당된 메모리 해제 (메모리 누수 방지) ~MyArray2D() { delete[] _matrix; } // 2. get(row, col): 값 읽기 (행 우선 순서 인덱싱) int get(int row, int col) const { if (row < 0 || row >= _rows || col < 0 || col >= _cols) { throw std::out_of_range("인덱스 범위를 벗어났습니다. (Out of Bound)"); } return _matrix[row * _cols + col]; } // 3. set(row, col, value): 값 쓰기 void set(int row, int col, int value) { if (row < 0 || row >= _rows || col < 0 || col >= _cols) { throw std::out_of_range("인덱스 범위를 벗어났습니다. (Out of Bound)"); } _matrix[row * _cols + col] = value; } // 4. num_rows(): 행 개수 반환 int num_rows() const { return _rows; } // 5. num_cols(): 열 개수 반환 int num_cols() const { return _cols; } }; int main() { try { MyArray2D arr2d(2, 3); arr2d.set(0, 0, 10); arr2d.set(1, 2, 99); std::cout << "0행 0열: " << arr2d.get(0, 0) << "
"; std::cout << "1행 2열: " << arr2d.get(1, 2) << "
"; } catch (const std::exception& e) { std::cerr << "에러: " << e.what() << "
"; } return 0; }

#include <iostream> #include <memory> #include <string> // 1. Node 구조체 정의 template <typename T> struct Node { T data; std::shared_ptr<Node<T>> left{nullptr}; // 왼쪽 자식 노드 std::shared_ptr<Node<T>> right{nullptr}; // 오른쪽 자식 노드 explicit Node(const T& val) : data(val) {} }; // 2. BinaryTree 클래스 정의 template <typename T> class BinaryTree { private: std::shared_ptr<Node<T>> root{nullptr}; // 내부 전용 생성자: 기존 노드 포인터로 서브 트리 객체를 포장(wrap)할 때 사용 // std::shared_ptr는 복사할 때마다 내부 참조 횟수(Reference Count)가 늘어나기 때문에 // 약간의 오버헤드가 발생할 수 있다. // std::move를 사용하면 복사 대신 소유권 자체를 그대로 이전(Move)한다. // 즉, 인자로 넘어온 node가 가지고 있던 노드 제어권을 성능 저하 없이 // root에게 넘겨준다. explicit BinaryTree(std::shared_ptr<Node<T>> node) : root(std::move(node)) {} public: // 기본 생성자 (공집합 트리 생성) BinaryTree() = default; // 루트 데이터를 받아서 생성하는 생성자 explicit BinaryTree(const T& root_data) { root = std::make_shared<Node<T>>(root_data); } // is_empty(): 현재 이진 트리가 공집합인지 확인 bool is_empty() const { return root == nullptr; } // get_root_data(): 루트 노드의 데이터 반환 // template class여서 발행하는 문제를 해결하기 위해서, 디폴트 매개변수 필요함 T get_root_data(T default_val = T{}) const { if (is_empty()) { return default_val; } return root->data; } // set_root_data(x): 루트 노드의 데이터를 x로 설정하거나 신규 생성 void set_root_data(const T& x) { if (is_empty()) { root = std::make_shared<Node<T>>(x); } else { root->data = x; } } // get_left_child(): 왼쪽 서브 트리 반환 BinaryTree get_left_child() const { if (!is_empty() && root->left != nullptr) { return BinaryTree(root->left); } return BinaryTree(); // 자식이 없으면 공집합 이진 트리 반환 } // get_right_child(): 오른쪽 서브 트리 반환 BinaryTree get_right_child() const { if (!is_empty() && root->right != nullptr) { return BinaryTree(root->right); } return BinaryTree(); } // set_left_child(sub): 왼쪽 자리에 새로운 서브 트리 sub 연결 void set_left_child(const BinaryTree& sub) { if (is_empty()) { std::cout << "공집합 트리에는 자식 서브 트리를 연결할 수 없습니다.
"; return; } root->left = (!sub.is_empty()) ? sub.root : nullptr; } // set_right_child(sub): 오른쪽 자리에 새로운 서브 트리 sub 연결 void set_right_child(const BinaryTree& sub) { if (is_empty()) { std::cout << "공집합 트리에는 자식 서브 트리를 연결할 수 없습니다.
"; return; } root->right = (!sub.is_empty()) ? sub.root : nullptr; } }; /* [트리 구조] A / \ B C / \ D E */ int main() { // 1. 서브 트리 생성 (Bottom-up 방식) BinaryTree<char> sub_d('D'); BinaryTree<char> sub_e('E'); BinaryTree<char> sub_b('B'); sub_b.set_left_child(sub_d); sub_b.set_right_child(sub_e); BinaryTree<char> sub_c('C'); // 2. 메인 트리 생성 및 연결 BinaryTree<char> tree; tree.set_root_data('A'); tree.set_left_child(sub_b); tree.set_right_child(sub_c); // 3. 데이터 조회 및 탐색 std::cout << "루트 데이터: " << tree.get_root_data() << "
"; BinaryTree<char> left_sub = tree.get_left_child(); std::cout << "루트의 왼쪽 자식 데이터: " << left_sub.get_root_data() << "
"; BinaryTree<char> left_left_sub = left_sub.get_left_child(); std::cout << "왼쪽 자식의 왼쪽 자식 데이터: " << left_left_sub.get_root_data() << "
"; return 0; }

#include <iostream> #include <vector> #include <cstddef> // std::size_t #include <utility> // std::swap template <typename T> class MaxHeap { private: std::vector<T> heap; // 0번 인덱스는 사용하지 않음 // 공통으로 사용되는 Down-Heap (더 큰 자식과 비교하여 아래로 내림) void down_heap(std::size_t current) { while (current * 2 <= size()) { std::size_t left = current * 2; std::size_t right = current * 2 + 1; std::size_t larger = left; if (right <= size() && heap[right] > heap[left]) { larger = right; } if (heap[current] >= heap[larger]) { break; } std::swap(heap[current], heap[larger]); current = larger; } } public: // 기본 생성자: 0번 인덱스를 비워두기 위해 기본값 1개 삽입 MaxHeap() { heap.push_back(T{}); } // 벡터를 인자로 받는 생성자 (heapify 수행) MaxHeap(const std::vector<T>& arr) { heap.push_back(T{}); // 0번 인덱스 더미 삽입 heapify(arr); } bool is_empty() const { return heap.size() <= 1; } std::size_t size() const { return heap.size() - 1; } // Up-Heap (부모와 비교하여 위로 올림) void push(const T& value) { heap.push_back(value); // 마지막에 노드를 추가 std::size_t current = size(); // 추가된 노드의 현재 위치 while (current > 1) { std::size_t parent = current / 2; if (heap[parent] >= heap[current]) { break; } std::swap(heap[parent], heap[current]); current = parent; } } // Pop (최댓값 추출) T pop() { if (is_empty()) { return T{}; } T max_val = heap[1]; T last_val = heap.back(); heap.pop_back(); if (!is_empty()) { heap[1] = last_val; down_heap(1); } return max_val; } // 임의의 배열을 O(N) 만에 힙으로 변환하는 바텀업(Bottom-up) 메서드 void heapify(const std::vector<T>& arr) { // 기존 데이터를 초기화하고 0번 더미 뒤에 배열 통째로 복사 heap.resize(1); heap.insert(heap.end(), arr.begin(), arr.end()); // 가장 마지막 부모 노드부터 루트(1)까지 역순으로 순회 // signed 타입(long long)을 사용하여 unsigned 언더플로 방지 for (long long current = static_cast<long long>(size() / 2); current >= 1; --current) { down_heap(static_cast<std::size_t>(current)); } } // 우선순위가 가장 높은 요소를 삭제하지 않고 반환 T peek() const { if (is_empty()) { return T{}; } return heap[1]; } // 힙 배열의 현재 상태 출력 (1번 인덱스부터) void display() const { std::cout << "힙 배열: ["; for (std::size_t i = 1; i <= size(); ++i) { std::cout << heap[i]; if (i < size()) std::cout << ", "; } std::cout << "]
"; } }; int main() { // 1. heapify 생성자를 이용한 O(N) 힙 구축 테스트 std::vector<int> data = {10, 40, 30, 5, 12, 50}; MaxHeap<int> heap(data); // 힙 배열 상태 출력 heap.display(); // 힙 배열: [50, 12, 40, 5, 10, 30] // Peek 결과 출력 std::cout << "Peek 결과 (최댓값 확인): " << heap.peek() << "
"; // 50 // Pop 결과 출력 std::cout << "Pop 결과: ["; std::size_t initial_size = heap.size(); for (std::size_t i = 0; i < initial_size; ++i) { std::cout << heap.pop(); if (i < initial_size - 1) std::cout << ", "; } std::cout << "]
"; // Pop 결과: [50, 40, 30, 12, 10, 5] return 0; }

#include <iostream> #include <vector> #include <string> class ArrayDecisionTree { private: std::vector<std::string> tree; bool is_leaf(int index) { // 리스트 범위를 벗어나거나 비어있거나, 문장이 '입니다.'로 끝나면 리프 노드로 간주 if (index >= tree.size() || tree[index].empty()) { return true; } return tree[index].find("입니다.") != std::string::npos; } public: ArrayDecisionTree() { // 0번 인덱스는 편의상 비워두고, 1번부터 루트 노드가 시작되도록 구성 // 인덱스 공식: 왼쪽 자식 = 2*i, 오른쪽 자식 = 2*i + 1 tree = { "", // 0번 (사용 안 함) "동물입니까?", // 1 (루트) "다리가 2개입니까?", // 2 (1의 왼쪽 자식) "키가 큽니까?", // 3 (1의 오른쪽 자식) "날 수 있습니까?", // 4 (2의 왼쪽 자식) "몸집이 사람보다 큽니까?", // 5 (2의 오른쪽 자식) "침엽수 입니까?", // 6 (3의 왼쪽 자식) "꽃입니까?", // 7 (3의 오른쪽 자식) "새입니다.", // 8 (4의 왼쪽 자식 - 리프) "타조나 닭입니다.", // 9 (4의 오른쪽 자식 - 리프) "코끼리입니다.", // 10 (5의 왼쪽 자식 - 리프) "개입니다.", // 11 (5의 오른쪽 자식 - 리프) "소나무입니다.", // 12 (6의 왼쪽 자식 - 리프) "대나무입니다.", // 13 (6의 오른쪽 자식 - 리프) "난초입니다.", // 14 (7의 왼쪽 자식 - 리프) "잔디입니다." // 15 (7의 오른쪽 자식 - 리프) }; } void play(int index = 1) { // 트리의 범위를 벗어난 경우 종료 if (index >= tree.size() || tree[index].empty()) { return; } std::string current_data = tree[index]; // 리프 노드(결과 도출)에 도달한 경우 if (is_leaf(index)) { std::cout << "
[결과]: " << current_data << "
"; return; } // 내부 노드(질문)인 경우 std::cout << "
Q. " << current_data << "
(y/n): "; std::string user_input; std::cin >> user_input; if (user_input == "y" || user_input == "yes") { // '예'일 경우 왼쪽 자식으로 이동 (인덱스: 2 * i) play(2 * index); } else { // '아니오'일 경우 오른쪽 자식으로 이동 (인덱스: 2 * i + 1) play(2 * index + 1); } } }; // --- 실행 테스트 --- int main() { ArrayDecisionTree dt; dt.play(1); // 루트인 1번 인덱스부터 시작 return 0; }

#include <iostream> #include <memory> #include <string> // 1. std::shared_ptr 기반 템플릿 노드 구조체 template <typename T> struct Node { T data; std::shared_ptr<Node<T>> left{nullptr}; // 왼쪽 자식 노드 std::shared_ptr<Node<T>> right{nullptr}; // 오른쪽 자식 노드 explicit Node(const T& val) : data(val) {} }; // 2. std::shared_ptr 기반 템플릿 이진 탐색 트리(BST) 클래스 template <typename T> class BST { // ========================================================= // --- 실제 재귀 호출이 일어나는 내부 헬퍼 함수 --- // ========================================================= private: std::shared_ptr<Node<T>> _insert_rec(std::shared_ptr<Node<T>> node, const T& data) { // 1. 기저 조건(Base Case): 빈자리를 발견하면 새 노드 생성 후 반환 if (node == nullptr) { return std::make_shared<Node<T>>(data); } // 2. 재귀 단계(Recursive Step): 값 비교 후 적절한 서브트리로 재귀 호출 및 포인터 재연결 if (data < node->data) { node->left = _insert_rec(node->left, data); } else if (data > node->data) { node->right = _insert_rec(node->right, data); } // data == node->data 인 경우(중복 값)는 변화 없이 진행 // 3. 갱신된 현재 노드 반환 return node; } public: std::shared_ptr<Node<T>> root; // 루트 데이터를 입력받는 생성자 explicit BST(const T& root_data) { root = std::make_shared<Node<T>>(root_data); } // 스마트 포인터 사용으로 소멸자를 직접 구현할 필요가 없음 (자동 메모리 해제) // 재귀적 검색 방식 std::shared_ptr<Node<T>> search(std::shared_ptr<Node<T>> node, const T& key) const { if (node == nullptr) { return nullptr; } if (node->data == key) { return node; } if (key < node->data) { return search(node->left, key); } else { return search(node->right, key); } } // 반복적 검색 방식 std::shared_ptr<Node<T>> search_iterative(const T& key) const { std::shared_ptr<Node<T>> current = root; while (current != nullptr) { if (key == current->data) { return current; } else if (key < current->data) { current = current->left; } else { current = current->right; } } return nullptr; } // ========================================================= // --- 추가된 재귀적 노드 삽입(insert) 메서드 --- // ========================================================= void insert(const T& data) { root = _insert_rec(root, data); } // ========================================================= // --- [추가] 반복적 노드 삽입(insert_iterative) 메서드 --- // ========================================================= void insert_iterative(const T& data) { // 1. 예외 처리: 트리가 비어있는 경우 if (root == nullptr) { root = std::make_shared<Node<T>>(data); return; } std::shared_ptr<Node<T>> parent = nullptr; std::shared_ptr<Node<T>> current = root; // 2. 탐색 및 위치 추적: 빈자리에 도달할 때까지 아래로 이동 while (current != nullptr) { parent = current; // 이동하기 전 부모 노드 기록 if (data < current->data) { current = current->left; } else if (data > current->data) { current = current->right; } } // 3. 노드 연결: parent 노드의 자식으로 새 노드 연결 if (data < parent->data) { parent->left = std::make_shared<Node<T>>(data); } else { parent->right = std::make_shared<Node<T>>(data); } } }; int main() { // --- 1. 루트 생성 (50) --- BST<int> bst(50); // --- 2. 재귀적 insert()를 통한 노드 자동 삽입 --- // 50 // / \ // 30 70 bst.insert(30); bst.insert(70); // --- 3. 반복적 insert_iterative()를 통한 노드 추가 삽입 --- // 50 // / \ // 30 70 // / \ // 20 40 bst.insert_iterative(20); bst.insert_iterative(40); // --- 4. 검색 테스트 (반복문 이용) --- int target1 = 40; auto result1 = bst.search_iterative(target1); if (result1 != nullptr) { std::cout << "[반복] 찾았습니다: " << result1->data << "
"; } else { std::cout << "[반복] 찾지 못했습니다.
"; } // --- 5. 검색 테스트 (재귀함수 이용) --- int target2 = 20; auto result2 = bst.search(bst.root, target2); if (result2 != nullptr) { std::cout << "[재귀] 찾았습니다: " << result2->data << "
"; } else { std::cout << "[재귀] 찾지 못했습니다.
"; } return 0; }

